# Minimal direct schema validator for this supplied schema (no jsonschema dependency).
def validate(x,s,path='$'):
 if 'enum' in s:assert x in s['enum'],path
 t=s.get('type')
 if t=='object':
  assert isinstance(x,dict),path
  for k in s.get('required',[]):assert k in x,path+'.'+k
  if not s.get('additionalProperties',True):assert set(x)<=set(s.get('properties',{})),path
  for k,v in x.items():
   if k in s.get('properties',{}):validate(v,s['properties'][k],path+'.'+k)
 elif t=='array':
  assert isinstance(x,list) and len(x)>=s.get('minItems',0),path
  for i,v in enumerate(x):validate(v,s.get('items',{}),path+str(i))
 elif t=='string':assert isinstance(x,str) and len(x)>=s.get('minLength',0),path
 elif t=='integer':assert type(x)==int,path
 elif t=='number':assert type(x) in (int,float),path
 if isinstance(x,(int,float)):
  if 'minimum' in s:assert x>=s['minimum'],path
  if 'maximum' in s:assert x<=s['maximum'],path
validate(load('pedagogical-variation.json'),json.load(open('/home/jake/Developer/Course_Academy/generate/pipeline/pedagogical-variation.schema.json')))
